<?php
namespace App\Console\Commands; use App\Services\Dapcode\CodeFormatterService; use App\Services\Dapcode\CodeMinifierService; use App\Services\Dapcode\IntegrityService; use App\Services\Dapcode\LicenseGuard; use Illuminate\Console\Command; use Illuminate\Support\Str; class CodeUnminifyCommand extends Command { protected $signature = 'code:unminify {target=all : Target: "all", "modules", "aegisguard", "routes" (termasuk middleware, helper, kernel & portofolio), module name (e.g. "Achievement"), or custom path} {--format : Force reformatting using code beautifier without reading vault} {--indent=4 : Number of spaces for indentation (default: 4)} {--clean-backup : Clear vaulted sourcemaps/backups after successful restore} {--force : Force operation without confirmation}'; protected $description = 'Unminify, restore original code from SourceMap Vault, or beautify code (AegisGuard protection, HMVC modules, and Routes with Portfolio Homepage, Middlewares, Helpers & Kernel)'; public function handle(CodeMinifierService $minifier, CodeFormatterService $formatter) { $target = (string) $this->argument('target'); $forceFormat = (bool) $this->option('format'); $indent = (int) $this->option('indent'); $cleanBackup = (bool) $this->option('clean-backup'); $force = (bool) $this->option('force'); $this->info("======================================================="); $this->info("     DAPCODE AEGISGUARD — PHP CODE UNMINIFIER          "); $this->info("======================================================="); $displayTarget = $target; if (in_array(strtolower($target), ['routes', 'route', 'portfolio', 'home'], true)) { $displayTarget = "{$target} (Seluruh File Routes, Middlewares, Helpers & Halaman Utama Portofolio)"; } elseif (in_array(strtolower($target), ['aegisguard', 'protection', 'dapcode', 'enc', 'encrypted'], true)) { $displayTarget = "{$target} (Kode Proteksi AegisGuard & File Enkripsi .enc)"; } elseif (in_array(strtolower($target), ['middlewares', 'middleware'], true)) { $displayTarget = "{$target} (Seluruh File Middleware & Http/Kernel.php)"; } elseif (in_array(strtolower($target), ['helpers', 'helper'], true)) { $displayTarget = "{$target} (Seluruh File Helper)"; } elseif (in_array(strtolower($target), ['kernel', 'http-kernel'], true)) { $displayTarget = "{$target} (File Http/Kernel.php)"; } $this->line("<comment>Target:</comment> <info>{$displayTarget}</info>"); $this->line("<comment>Mode  :</comment> " . ($forceFormat ? '<comment>Force Code Beautifier/Formatter</comment>' : '<info>Auto (Restore from Vault if available, else Beautify)</info>')); $this->line("<comment>Indent:</comment> <info>{$indent} spaces</info>"); $this->newLine(); $files = $minifier->getTargetFiles($target); if (empty($files)) { $this->error("Tidak ada file PHP yang ditemukan untuk target [{$target}]."); return 1; } $this->line("Ditemukan <info>" . count($files) . "</info> file target."); if ( ! $force && count($files) > 10 && $this->input->isInteractive()) { if ( ! $this->confirm("Apakah Anda yakin ingin me-unminify / memformat " . count($files) . " file PHP ini?", true)) { $this->warn("Operasi dibatalkan oleh pengguna."); return 0; } } $results = []; $restoredVaultCount = 0; $restoredBakCount = 0; $beautifiedCount = 0; $bar = $this->output->createProgressBar(count($files)); $bar->start(); foreach ($files as $file) { $res = $formatter->unminifyFile($file, ! $forceFormat, $forceFormat, $indent, $cleanBackup ); if ($res['success']) { $relPath = Str::after($file, base_path() . DIRECTORY_SEPARATOR); if ($res['mode'] === 'vault_restored') { $restoredVaultCount++; $status = '<info>Restored (Vault)</info>'; } elseif ($res['mode'] === 'backup_restored') { $restoredBakCount++; $status = '<info>Restored (.bak)</info>'; } else { $beautifiedCount++; $status = '<comment>Beautified</comment>'; } $typeLabel = '<comment>PHP</comment>'; if (Str::endsWith($file, '.blade.php')) { $typeLabel = '<info>Blade</info>'; } elseif (Str::endsWith($file, '.json')) { $typeLabel = '<fg=cyan>JSON</>'; } elseif (Str::endsWith($file, '.enc')) { $typeLabel = '<question>ENC</question>'; } $results[] = [ 'file' => $relPath, 'type' => $typeLabel, 'status' => $status, 'size' => $this->formatBytes($res['size']), ]; } $bar->advance(); } $bar->finish(); $this->newLine(2); $this->table(['File Target', 'Type', 'Action / Status', 'New Size'], $results ); $this->info("======================================================="); $this->info(" [SELESAI] " . count($results) . " file berhasil di-unminify!"); $this->line(" Dipulihkan dari SourceMap Vault : <info>{$restoredVaultCount}</info> file (100% kode asli)"); if ($restoredBakCount > 0) { $this->line(" Dipulihkan dari file .bak       : <info>{$restoredBakCount}</info> file"); } $this->line(" Diformat ulang (Beautifier)     : <info>{$beautifiedCount}</info> file"); if ($cleanBackup) { $this->line(" Vault sourcemaps / file .bak telah dibersihkan."); } $this->info("======================================================="); IntegrityService::recordCoreFilesManifest(); LicenseGuard::clearCache(); return 0; } protected function formatBytes($bytes, $precision = 2) { if ($bytes <= 0) { return '0 B'; } $units = ['B', 'KB', 'MB', 'GB']; $base = log($bytes, 1024); $pow = floor($base); return round(pow(1024, $base - $pow), $precision) . ' ' . ($units[$pow] ?? 'B'); } }